let _markdown = "\n\n<FeedbackBlock id=\"444fa5dc6030049b\" body=\"In Docusaurus, there's an Admonition syntax.\">\n  In Docusaurus, there's an [Admonition syntax](https://docusaurus.io/docs/markdown-features/admonitions).\n</FeedbackBlock>\n\n<FeedbackBlock id=\"fcc8efe6c4425549\" body=\"For people migrating from Docusaurus, you can enable this remark plugin to support the Admonition syntax.\">\n  For people migrating from Docusaurus, you can enable this remark plugin to support the Admonition syntax.\n</FeedbackBlock>\n\nUsage [#usage]\n\n<FeedbackBlock id=\"d2d66c49d7a244b7\" body=\"It requires remark-directive to work.\">\n  It requires `remark-directive` to work.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm i remark-directive\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add remark-directive\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add remark-directive\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add remark-directive\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"197c49e6458272ac\" body=\"Configure both plugins in your config.\">\n  Configure both plugins in your config.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Fumadocs MDX\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Fumadocs MDX\">\n      Fumadocs MDX\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"MDX Compiler\">\n      MDX Compiler\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Fumadocs MDX\">\n    ```ts title=\"source.config.ts\" \n    import remarkDirective from 'remark-directive';\n    import { remarkDirectiveAdmonition } from 'fumadocs-core/mdx-plugins';\n    import { defineConfig } from 'fumadocs-mdx/config';\n\n    export default defineConfig({\n      mdxOptions: {\n        remarkPlugins: [remarkDirective, remarkDirectiveAdmonition],\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"MDX Compiler\">\n    ```ts\n    import remarkDirective from 'remark-directive';\n    import { remarkDirectiveAdmonition } from 'fumadocs-core/mdx-plugins';\n    import { compile } from '@mdx-js/mdx';\n\n    await compile('...', {\n      remarkPlugins: [remarkDirective, remarkDirectiveAdmonition],\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nExample [#example]\n\n<CodeBlockTabs defaultValue=\"Input\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Input\">\n      Input\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Output\">\n      Output\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Input\">\n    ```md\n    :::tip[This is a `title`]\n\n    Hello World\n\n    :::\n\n    :::warning\n\n    Hello World\n\n    :::\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Output\">\n    ```mdx\n    <CalloutContainer type='info'>\n      <CalloutTitle>This is a `title`</CalloutTitle>\n      <CalloutDescription>\n\n        Hello World\n\n      </CalloutDescription>\n    </CalloutContainer>\n\n    <CalloutContainer type='warning'>\n      <CalloutDescription>\n\n        Hello World\n\n      </CalloutDescription>\n    </CalloutContainer>\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nWhen to use [#when-to-use]\n\n<FeedbackBlock\n  id=\"86c7eec5a28e6c91\"\n  body=\"We highly recommend using the JSX syntax of MDX instead.\nIt's more flexible, some editors support IntelliSense in MDX files.\"\n>\n  We highly recommend using the JSX syntax of MDX instead.\n  It's more flexible, some editors support IntelliSense in MDX files.\n</FeedbackBlock>\n\n```mdx\n<Callout type='warn'>\n\nHello World\n\n</Callout>\n```\n";
